with target_team as (select id from teams where join_code = 'BANTAM-B7X2')
insert into categories (team_id, unit, name)
select id, v.unit, v.name from target_team, (values
  ('offense', 'Run'),
  ('offense', 'Pass'),
  ('offense', 'Uncategorized'),
  ('defense', 'Uncategorized'),
  ('specialTeams', 'Uncategorized')
) as v(unit, name);
